_STATUS_LOCAL_PATH_RE = re.compile(
    r"(/" r"Users/[^\s\"'`<>]+(?:\s+[^\s\"'`<>]+)*|/private/[^\s\"'`<>]+|/var/folders/[^\s\"'`<>]+|/tmp/[^\s\"'`<>]+)"
)
_STATUS_TOOL_RUN_OUTPUT_PREVIEW_RE = re.compile(
    r"(tool run #\d+\s+[\w.-]+\s+\[[^\]]+\]\s+(?:ok|failed/blocked|failed|blocked):)\s+.*",
    re.IGNORECASE,
)
