def _status_scrub_text(text: str) -> str:
    return _STATUS_LOCAL_PATH_RE.sub("<local-path>", text)


def _status_scrub_dashboard_preview(value: object) -> str:
    text = _status_scrub_text(str(value or ""))
    return _STATUS_TOOL_RUN_OUTPUT_PREVIEW_RE.sub(r"\1 <output suppressed>", text)


@dataclass(frozen=True)
class _StatusRiskView:
    name: str


@dataclass(frozen=True)
class _StatusToolView:
    name: str
    risk: _StatusRiskView
    description: str
    toolset: str


def _status_non_negative_int(value: Any, default: int = 0) -> int:
    if isinstance(value, bool):
        return default
    try:
        number = int(value)
    except Exception:
        return default
    return max(0, number)


def _status_count_map(value: Any) -> dict[str, int]:
    if not isinstance(value, dict):
        return {}
    counts: dict[str, int] = {}
    for raw_key, raw_count in value.items():
        try:
            key = _status_scrub_text(str(raw_key or "")).strip()
        except Exception:
            key = "<unreadable>"
        if not key:
            key = "unknown"
        counts[key] = counts.get(key, 0) + _status_non_negative_int(raw_count)
    return counts


def _status_text(value: Any, default: str = "", max_chars: int = 220) -> str:
    if value is None:
        return default
    try:
        text = _status_scrub_text(str(value)).strip()
    except Exception:
        return default
    if not text:
        return default
    if max_chars > 0:
        return text[:max_chars]
    return text


def _status_text_list(value: Any, limit: int = 8, max_chars: int = 220) -> list[str]:
    if not isinstance(value, list):
        return []
    items: list[str] = []
    for item in value[:limit]:
        text = _status_text(item, max_chars=max_chars)
        if text:
            items.append(text)
    return items


def _status_cockpit_command_queue(value: Any, limit: int = 8) -> list[dict[str, str]]:
    if not isinstance(value, list):
        return []
    queue: list[dict[str, str]] = []
    for item in value[:limit]:
        if isinstance(item, dict):
            command = _status_text(item.get("command"), max_chars=220)
            kind = _status_text(item.get("kind"), default="diagnostic", max_chars=80)
            lane_key = _status_text(item.get("lane_key"), max_chars=80)
            lane_title = _status_text(item.get("lane_title"), max_chars=120)
        else:
            command = _status_text(item, max_chars=220)
            kind = "diagnostic"
            lane_key = ""
            lane_title = ""
        if not command:
            continue
        queue.append(
            {
                "command": command,
                "kind": kind or "diagnostic",
                "lane_key": lane_key,
                "lane_title": lane_title,
            }
        )
    return queue


def _status_cockpit_coverage_summary(value: Any = None) -> dict[str, Any]:
    coverage = value if isinstance(value, dict) else {}
    return {
        "lane_count": _status_non_negative_int(coverage.get("lane_count")),
        "tool_ready_count": _status_non_negative_int(coverage.get("tool_ready_count")),
        "smoke_ready_count": _status_non_negative_int(coverage.get("smoke_ready_count")),
        "hidden_tool_metadata_count": _status_non_negative_int(coverage.get("hidden_tool_metadata_count")),
        "hidden_smoke_metadata_count": _status_non_negative_int(coverage.get("hidden_smoke_metadata_count")),
        "approval_required_count": _status_non_negative_int(coverage.get("approval_required_count")),
        "auto_run_safe_count": _status_non_negative_int(coverage.get("auto_run_safe_count")),
        "coverage_ready": bool(coverage.get("coverage_ready") is True),
        "summary": str(coverage.get("summary") or ""),
    }


def _status_cockpit_trust_summary(value: Any = None) -> dict[str, Any]:
    summary = value if isinstance(value, dict) else {}
    return {
        "lane_count": _status_non_negative_int(summary.get("lane_count")),
        "trust_ready_lane_count": _status_non_negative_int(summary.get("trust_ready_lane_count")),
        "trust_partial_lane_count": _status_non_negative_int(summary.get("trust_partial_lane_count")),
        "trust_check_count": _status_non_negative_int(summary.get("trust_check_count")),
        "trust_ready_check_count": _status_non_negative_int(summary.get("trust_ready_check_count")),
        "trust_ready": bool(summary.get("trust_ready") is True),
        "trust_non_authorizing": bool(summary.get("trust_non_authorizing") is True),
        "summary": str(summary.get("summary") or ""),
    }


def _status_cockpit_coverage_ready(value: Any, coverage_summary: dict[str, Any]) -> bool:
    return bool(value is True and coverage_summary.get("coverage_ready") is True)


def _status_tool_view(tool: Any) -> tuple[_StatusToolView | None, int]:
    unreadable = 0
    try:
        name = _status_scrub_text(str(tool.name or "")).strip()
    except Exception:
        return None, 1
    if not name or _STATUS_LOCAL_PATH_RE.search(name):
        return None, 1
    try:
        risk_name = _status_scrub_text(str(tool.risk.name or "")).strip()
    except Exception:
        risk_name = "UNKNOWN"
        unreadable += 1
    if not risk_name or _STATUS_LOCAL_PATH_RE.search(risk_name):
        risk_name = "UNKNOWN"
        unreadable += 1
    try:
        description = _status_scrub_text(str(tool.description or "")).strip()
    except Exception:
        description = "<unreadable>"
        unreadable += 1
    try:
        toolset = _status_scrub_text(str(tool.toolset or "unknown")).strip()
    except Exception:
        toolset = "unknown"
        unreadable += 1
    if not toolset or _STATUS_LOCAL_PATH_RE.search(toolset):
        toolset = "unknown"
        unreadable += 1
    return _StatusToolView(name=name, risk=_StatusRiskView(risk_name), description=description, toolset=toolset), unreadable


def _status_registry_tools(runtime: JarvisRuntime) -> tuple[list[_StatusToolView], int]:
    unreadable = 0
    raw_registry = getattr(runtime.registry, "_tools", None)
    if isinstance(raw_registry, dict):
        try:
            raw_tools = list(raw_registry.values())
        except Exception:
            return [], 1
    else:
        try:
            raw_tools = runtime.registry.list()
        except Exception:
            return [], 1
    readable: list[_StatusToolView] = []
    for tool in raw_tools:
        view, hidden = _status_tool_view(tool)
        unreadable += hidden
        if view is not None:
            readable.append(view)
    return sorted(readable, key=lambda tool: tool.name), unreadable


def _status_row_has_keys(row: Any, keys: tuple[str, ...]) -> bool:
    try:
        if isinstance(row, dict):
            row_keys = row.keys()
        else:
            row_keys = row.keys()
    except Exception:
        return False
    try:
        return all(key in row_keys for key in keys)
    except Exception:
        return False


def _status_row_value(row: Any, key: str, default: Any = None) -> Any:
    try:
        return row[key]
    except Exception:
        return default


def _status_row_text(row: Any, key: str, default: str = "") -> str:
    value = _status_row_value(row, key, default)
    try:
        return _status_scrub_text(str(value or ""))
    except Exception:
        return default


_STATUS_ROW_MISSING = object()


def _status_row_bool(row: Any, key: str, default: bool | None = False) -> bool | None:
    value = _status_row_value(row, key, _STATUS_ROW_MISSING)
    if value is _STATUS_ROW_MISSING:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, int) and value in {0, 1}:
        return bool(value)
    return None


def _status_readable_tool_runs(rows: list[Any]) -> tuple[list[dict[str, Any]], int]:
    readable: list[dict[str, Any]] = []
    unreadable = 0
    for row in rows:
        if not _status_row_has_keys(row, ("id", "tool_name", "ok", "risk")):
            unreadable += 1
            continue
        tool_name = _status_row_text(row, "tool_name")
        risk = _status_row_text(row, "risk")
        if not tool_name or not risk:
            unreadable += 1
            continue
        ok = _status_row_bool(row, "ok", default=None)
        approved = _status_row_bool(row, "approved", default=False)
        if ok is None or approved is None:
            unreadable += 1
            continue
        readable.append(
            {
                "id": _status_row_text(row, "id"),
                "session_id": _status_row_text(row, "session_id"),
                "tool_name": tool_name,
                "risk": risk,
                "ok": ok,
                "approved": approved,
                "approval_id": (
                    _status_row_text(row, "approval_id") if _status_row_has_keys(row, ("approval_id",)) else None
                ),
                "output": _status_row_text(row, "output"),
                "metadata": _status_row_text(row, "metadata", "{}") or "{}",
                "created_at": _status_row_text(row, "created_at"),
            }
        )
    return readable, unreadable


def _status_looks_like_sha256(value: Any) -> bool:
    return bool(re.fullmatch(r"[0-9a-fA-F]{64}", str(value or "").strip()))


def _status_metadata_bool(value: Any, default: bool = False) -> bool:
    if value is True:
        return True
    if value is False:
        return False
    return default


def _status_metadata_bool_or_handoff(value: Any, handoff: Any) -> bool:
    if value is None:
        return bool(handoff)
    return _status_metadata_bool(value)


def _status_metadata_any_bool(*values: Any) -> bool:
    return any(_status_metadata_bool(value) for value in values)


def _status_metadata_list(value: Any) -> list[Any]:
    if isinstance(value, list):
        return value
    return []


def _status_checkpoint_recovery_execute_handoff_default(key: str) -> Any:
    if key.endswith(("_fields", "_missing", "_required_evidence", "_proof_queue", "_rows", "_signals")):
        return []
    if key.endswith("_count"):
        return 0
    if key.endswith(("_sha256", "_state", "_command", "_boundary", "_gate_state")):
        return ""
    return False


def _status_checkpoint_recovery_execute_handoff_mirror_was_present(metadata: dict[str, Any]) -> bool:
    prefix = "checkpoint_recovery_execute_handoff_"
    for key, value in metadata.items():
        if not key.startswith(prefix) or key.endswith("_invalid_reason"):
            continue
        if value != _status_checkpoint_recovery_execute_handoff_default(key):
            return True
    return False


def _status_vetted_checkpoint_recovery_execute_metadata(metadata: dict[str, Any]) -> dict[str, Any]:
    response_metadata = dict(metadata)
    existing_invalid_reason = str(
        response_metadata.get("checkpoint_recovery_execute_handoff_invalid_reason") or ""
    )
    checkpoint_recovery_execute_handoff = response_metadata.get("checkpoint_recovery_execute_handoff")
    checkpoint_recovery_execute_handoff_was_present = isinstance(
        checkpoint_recovery_execute_handoff, dict
    ) and bool(checkpoint_recovery_execute_handoff)
    checkpoint_recovery_execute_handoff_mirror_was_present = (
        _status_checkpoint_recovery_execute_handoff_mirror_was_present(response_metadata)
    )
    if not isinstance(checkpoint_recovery_execute_handoff, dict):
        checkpoint_recovery_execute_handoff = {}
    checkpoint_recovery_execute_handoff_ready = bool(
        checkpoint_recovery_execute_handoff
        and _checkpoint_recovery_execute_handoff_ready(response_metadata)
    )
    checkpoint_recovery_execute_handoff_token_sha256 = ""
    if checkpoint_recovery_execute_handoff_ready:
        checkpoint_recovery_execute_handoff_token_sha256 = str(
            response_metadata.get("checkpoint_recovery_execute_handoff_token_sha256") or ""
        )
    checkpoint_recovery_execute_handoff_token_present = (
        checkpoint_recovery_execute_handoff_ready
        and response_metadata.get("checkpoint_recovery_execute_handoff_token_present") is True
        and checkpoint_recovery_execute_handoff.get("handoff_token_present") is True
        and _status_looks_like_sha256(checkpoint_recovery_execute_handoff_token_sha256)
    )
    if not checkpoint_recovery_execute_handoff_token_present:
        invalid_reason = (
            existing_invalid_reason
            or "invalid_or_stale_checkpoint_recovery_execute_handoff"
            if (
                existing_invalid_reason
                or
                checkpoint_recovery_execute_handoff_was_present
                or checkpoint_recovery_execute_handoff_mirror_was_present
            )
            else ""
        )
        checkpoint_recovery_execute_handoff_ready = False
        checkpoint_recovery_execute_handoff = {}
        checkpoint_recovery_execute_handoff_token_sha256 = ""
        for key in list(response_metadata):
            if key.startswith("checkpoint_recovery_execute_handoff_"):
                response_metadata[key] = _status_checkpoint_recovery_execute_handoff_default(key)
        response_metadata["checkpoint_recovery_execute_handoff_invalid_reason"] = invalid_reason
    else:
        response_metadata["checkpoint_recovery_execute_handoff_invalid_reason"] = ""
    response_metadata.update(
        {
            "checkpoint_recovery_execute_handoff": checkpoint_recovery_execute_handoff,
            "checkpoint_recovery_execute_handoff_ready": checkpoint_recovery_execute_handoff_ready,
            "checkpoint_recovery_execute_handoff_token_sha256": checkpoint_recovery_execute_handoff_token_sha256,
            "checkpoint_recovery_execute_handoff_token_present": checkpoint_recovery_execute_handoff_token_present,
            "checkpoint_recovery_execute_handoff_invalid_reason": response_metadata.get(
                "checkpoint_recovery_execute_handoff_invalid_reason", ""
            ),
        }
    )
    return response_metadata


def _hud_metrics_payload() -> dict[str, Any]:
    """Real local system telemetry for the HUD meters (read-only, no deps).

    cpu: 1-minute load average as a % of cores. mem: fraction of pages that
    are active+wired per vm_stat. Any failure yields None for that field so
    the UI keeps its decorative fallback instead of showing wrong numbers.
    """
    cpu_pct: int | None = None
    mem_pct: int | None = None
    try:
        cores = os.cpu_count() or 1
        cpu_pct = max(0, min(100, round(os.getloadavg()[0] / cores * 100)))
    except Exception:
        cpu_pct = None
    try:
        out = subprocess.run(["vm_stat"], capture_output=True, text=True, timeout=3).stdout
        pages: dict[str, int] = {}
        for line in out.splitlines():
            if ":" in line:
                key, _, raw = line.partition(":")
                digits = "".join(ch for ch in raw if ch.isdigit())
                if digits:
                    pages[key.strip().lower()] = int(digits)
        used = pages.get("pages active", 0) + pages.get("pages wired down", 0)
        free = pages.get("pages free", 0) + pages.get("pages inactive", 0) + pages.get("pages speculative", 0)
        total = used + free + pages.get("pages occupied by compressor", 0)
        if total > 0:
            mem_pct = max(0, min(100, round(used / total * 100)))
    except Exception:
        mem_pct = None
    return {
        "ok": True,
        "cpu_percent": cpu_pct,
        "memory_percent": mem_pct,
        "safety": "Read-only local system telemetry (load average and vm_stat). No personal data, no tools, no approvals.",
    }


def _status_safe_value(value: Any) -> Any:
    if value is None or isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return value if math.isfinite(value) else None
    if isinstance(value, str):
        return _status_scrub_text(value)
    if isinstance(value, dict):
        safe: dict[str, Any] = {}
        for key, item in value.items():
            try:
                safe_key = _status_scrub_text(str(key)).strip()
            except Exception:
                safe_key = "<unreadable>"
            if not safe_key:
                safe_key = "unknown"
            safe[safe_key] = _status_safe_value(item)
        return safe
    if isinstance(value, list):
        return [_status_safe_value(item) for item in value]
    if isinstance(value, tuple):
        return [_status_safe_value(item) for item in value]
    try:
        return _status_scrub_text(str(value))
    except Exception:
        return "<unreadable>"


def _subagent_fleet_status(runtime: JarvisRuntime) -> dict[str, Any]:
    fleet = getattr(runtime, "subagent_fleet", None)
    if fleet is None:
        snapshot = subagent_fleet_status_snapshot(None)
        snapshot["diagnostic"] = "subagent_fleet_missing"
        return snapshot
    return subagent_fleet_status_snapshot(lambda: fleet)


