def _metadata_projection(metadata: dict[str, Any], fields: list[str]) -> dict[str, Any]:
    return {field: metadata.get(field) for field in fields}


def _status_projection_contract(endpoint: str, metadata: dict[str, Any], fields: list[str]) -> dict[str, Any]:
    field_set = set(fields)
    rows = [
        {
            "field": field,
            "present_in_metadata": field in metadata,
            "projected_to_api": True,
            "authorizes_execution": False,
            "authorizes_local_safe_step": False,
            "authorizes_risky_work": False,
            "authorizes_approval": False,
            "authorizes_os_wake_lock": False,
            "authorizes_model_call": False,
            "authorizes_tool_execution": False,
            "authorizes_personal_data_read": False,
            "authorizes_external_side_effect": False,
            "authorizes_timebox_reuse": False,
            "reusable_for_next_review": False,
        }
        for field in fields
    ]
    group_rows = [
        {
            "group": group,
            "fields": group_fields,
            "field_count": len(group_fields),
            "fields_in_projection": all(field in field_set for field in group_fields),
            "fields_present_in_metadata": sum(1 for field in group_fields if field in metadata),
            "projected_to_api": True,
            "authorizes_execution": False,
            "authorizes_local_safe_step": False,
            "authorizes_risky_work": False,
            "authorizes_approval": False,
            "authorizes_os_wake_lock": False,
            "authorizes_model_call": False,
            "authorizes_tool_execution": False,
            "authorizes_personal_data_read": False,
            "authorizes_external_side_effect": False,
            "authorizes_timebox_reuse": False,
            "reusable_for_next_review": False,
        }
        for group, group_fields in AUTONOMY_STATUS_PROJECTION_FIELD_GROUPS.items()
    ]
    digest_payload = {
        "endpoint": endpoint,
        "fields": [[field, metadata.get(field)] for field in fields],
        "rows": rows,
        "group_rows": group_rows,
        "authorizes_execution": False,
        "authorizes_local_safe_step": False,
        "authorizes_risky_work": False,
        "authorizes_approval": False,
        "authorizes_os_wake_lock": False,
        "authorizes_model_call": False,
        "authorizes_tool_execution": False,
        "authorizes_personal_data_read": False,
        "authorizes_external_side_effect": False,
        "authorizes_timebox_reuse": False,
        "reusable_for_next_review": False,
    }
    token = hashlib.sha256(
        json.dumps(digest_payload, sort_keys=True, default=str).encode("utf-8")
    ).hexdigest()
    return {
        "status_projection_contract_endpoint": endpoint,
        "status_projection_contract_fields": fields,
        "status_projection_contract_field_count": len(fields),
        "status_projection_contract_rows": rows,
        "status_projection_contract_row_count": len(rows),
        "status_projection_contract_group_rows": group_rows,
        "status_projection_contract_group_row_count": len(group_rows),
        "status_projection_contract_token_sha256": token,
        "status_projection_contract_token_present": True,
        "status_projection_contract_authorizes_execution": False,
        "status_projection_contract_authorizes_local_safe_step": False,
        "status_projection_contract_authorizes_risky_work": False,
        "status_projection_contract_authorizes_approval": False,
        "status_projection_contract_authorizes_os_wake_lock": False,
        "status_projection_contract_authorizes_model_call": False,
        "status_projection_contract_authorizes_tool_execution": False,
        "status_projection_contract_authorizes_personal_data_read": False,
        "status_projection_contract_authorizes_external_side_effect": False,
        "status_projection_contract_authorizes_timebox_reuse": False,
        "status_projection_contract_reusable_for_next_review": False,
        "next_status_projection_requires_fresh_runtime_packet": True,
    }


