def _after_action_learning_summary(runtime: JarvisRuntime) -> dict[str, Any]:
    try:
        tool = runtime.registry.get("after_action_learning_packet")
    except KeyError:
        return {
            "verdict": "TOOL_MISSING",
            "run_id": None,
            "tool_name": "",
            "command": "",
            "recovery_command": "",
            "learning_candidates": [],
            "line": "After-action learning tool is not registered.",
        }

    try:
        result = tool.handler({"limit": 30})
    except Exception as exc:
        diagnostic = type(exc).__name__
        return {
            "verdict": "UNAVAILABLE",
            "run_id": None,
            "tool_name": "",
            "command": "after-action learning packet",
            "recovery_command": "",
            "learning_candidates": [],
            "diagnostic": diagnostic,
            "line": f"After-action learning unavailable. Diagnostic: {diagnostic}.",
        }
    metadata = result.metadata
    run_id = metadata.get("run_id")
    command = f"after-action learning packet {run_id}" if run_id else "after-action learning packet"
    candidates = metadata.get("learning_candidate_names")
    if not isinstance(candidates, list):
        candidates = []
    try:
        health_result = runtime.registry.get("execution_health_report").handler({"limit": 30})
        health_metadata = health_result.metadata
    except Exception:
        health_metadata = {}
    line = "No recent run is ready for learning review."
    if run_id:
        line = f"Run #{run_id} {metadata.get('tool_name', '')}: {metadata.get('verdict', 'READY')}"
    elif metadata.get("verdict"):
        line = str(metadata["verdict"])
    return {
        "verdict": str(metadata.get("verdict") or ("READY" if result.ok else "ERROR")),
        "run_id": run_id,
        "tool_name": str(metadata.get("tool_name") or ""),
        "risk": str(metadata.get("risk") or ""),
        "ok": _status_metadata_bool(metadata.get("ok")) if "ok" in metadata else None,
        "approved": _status_metadata_bool(metadata.get("approved")) if "approved" in metadata else None,
        "approval_problem": _status_metadata_bool(metadata.get("approval_problem")),
        "command": command,
        "verification_command": str(metadata.get("verification_command") or ""),
        "recovery_command": str(metadata.get("recovery_command") or ""),
        "regression_command": _status_scrub_dashboard_preview(metadata.get("regression_command") or ""),
        "next_command": _status_scrub_dashboard_preview(metadata.get("next_command") or ""),
        "next_commands": [
            _status_scrub_dashboard_preview(command)
            for command in (metadata.get("next_commands") or [])[:6]
        ],
        "next_command_count": int(metadata.get("next_command_count") or 0),
        "recovery_closure_state": str(health_metadata.get("recovery_closure_state") or ""),
        "recovery_closure_ready_to_retry": _status_metadata_bool(
            health_metadata.get("recovery_closure_ready_to_retry")
        ),
        "recovery_closure_target_run_id": health_metadata.get("recovery_closure_target_run_id"),
        "recovery_closure_target_tool_name": str(health_metadata.get("recovery_closure_target_tool_name") or ""),
        "recovery_closure_target_verification_receipts": int(health_metadata.get("recovery_closure_target_verification_receipts") or 0),
        "recovery_closure_target_recovery_packets": int(health_metadata.get("recovery_closure_target_recovery_packets") or 0),
        "recovery_closure_target_after_action_learning_packets": int(health_metadata.get("recovery_closure_target_after_action_learning_packets") or 0),
        "recovery_closure_missing": [str(item) for item in (health_metadata.get("recovery_closure_missing") or [])],
        "recovery_closure_missing_count": int(health_metadata.get("recovery_closure_missing_count") or 0),
        "recovery_closure_required_commands": [
            _status_scrub_dashboard_preview(command)
            for command in (health_metadata.get("recovery_closure_required_commands") or [])[:6]
        ],
        "recovery_closure_proof_queue": [
            _status_scrub_dashboard_preview(command)
            for command in (health_metadata.get("recovery_closure_proof_queue") or [])[:6]
        ],
        "recovery_closure_proof_queue_count": int(health_metadata.get("recovery_closure_proof_queue_count") or 0),
        "recovery_closure_next_required_command": str(
            health_metadata.get("recovery_closure_next_required_command")
            or health_metadata.get("recovery_closure_next_proof_command")
            or ""
        ),
        "recovery_closure_next_proof_command": str(health_metadata.get("recovery_closure_next_proof_command") or ""),
        "execution_health_command": "execution health report",
        "learning_candidates": [_status_scrub_dashboard_preview(candidate) for candidate in candidates[:4]],
        "line": line,
    }


def _approval_queue_item(row) -> dict[str, Any]:
    category, concern, safer_check = _risk_review_for(row["tool_name"], row["user_input"])
    approval_id = int(row["id"])
    return {
        "id": approval_id,
        "tool_name": row["tool_name"],
        "user_input": row["user_input"],
        "created_at": row["created_at"],
        "status": row["status"],
        "risk_category": category,
        "risk_concern": concern,
        "safer_check": safer_check,
        "decision_matrix": {
            "approve_if": (
                f"the operator still wants approval #{approval_id} now, the stored request is exact, "
                "and the expected result is verifiable."
            ),
            "dismiss_if": (
                "The request is stale, broad, surprising, private, destructive, aimed at the wrong "
                "app/account/file, or no longer needed."
            ),
            "narrow_first_if": (
                "The target, command, path, text, coordinates, recipient, or account is unclear."
            ),
            "ask_if": f"The `{category}` risk is acceptable but scope or success is still ambiguous.",
        },
        "commands": {
            "detail": f"approval detail {approval_id}",
            "readiness": f"approval readiness {approval_id}",
            "packet": f"approval packet {approval_id}",
            "proof": f"approval chain proof {approval_id}",
            "approve": f"approve approval {approval_id}",
            "dismiss": f"dismiss approval {approval_id}",
        },
    }


def _approval_handoff(row) -> dict[str, Any]:
    approval = _approval_queue_item(row)
    commands = approval["commands"]
    return {
        "id": approval["id"],
        "tool_name": approval["tool_name"],
        "user_input": approval["user_input"],
        "status": approval["status"],
        "risk_category": approval["risk_category"],
        "risk_concern": approval["risk_concern"],
        "safer_check": approval["safer_check"],
        "first_safe_command": commands["readiness"],
        "readiness_command": commands["readiness"],
        "last_look_command": commands["packet"],
        "proof_command": commands["proof"],
        "approve_command": commands["approve"],
        "dismiss_command": commands["dismiss"],
        "commands": commands,
    }


def _storage_summary(storage: dict[str, Any]) -> list[str]:
    mode = "workspace-local fallback notes" if _status_metadata_bool(storage.get("workspace_local_notes")) else "configured note vault"
    issues = _status_metadata_list(storage.get("issues"))
    recovery_required = _status_metadata_bool(storage.get("recovery_required"), default=bool(issues))
    recovery_check_tool_command = str(storage.get("recovery_check_tool_command") or "")
    recovery_check_command = str(storage.get("recovery_check_command") or V3_BOOTSTRAP_CHECK_COMMAND)
    recovery_command = str(storage.get("recovery_command") or V3_BOOTSTRAP_WRITE_COMMAND)
    proof_queue = list(storage.get("readiness_proof_queue") or storage.get("readiness_next_commands") or [])
    lines = [
        f"Status: {storage.get('status', 'unknown')}",
        f"Mode: {mode}",
        f"Database: `{storage.get('db_path', '')}`",
        f"Jarvis note vault: `{storage.get('obsidian_vault', '')}`",
        f"Jarvis note root: `{storage.get('obsidian_root_path', '')}`",
        f"Vault writable: {'yes' if _status_metadata_bool(storage.get('obsidian_vault_writable')) else 'no'}",
        f"Root writable: {'yes' if _status_metadata_bool(storage.get('obsidian_root_writable')) else 'no'}",
    ]
    if issues:
        lines.extend(f"Issue: {issue}" for issue in issues[:4])
    else:
        lines.append("Issues: none.")
    lines.extend(
        [
            f"Recovery required before completion claim: {'yes' if recovery_required else 'no'}.",
            f"Recovery check: `{recovery_check_tool_command or recovery_check_command}`",
            "Recovery check API: `/api/storage-recovery-check`",
            f"Shell recovery check: `{recovery_check_command}`",
            f"Recovery write: `{recovery_command}` only after the check reports configured storage ready.",
            f"Proof ladder: {', '.join(f'`{command}`' for command in proof_queue) if proof_queue else 'none'}.",
        ]
    )
    return lines


def _storage_handoff(storage: dict[str, Any]) -> dict[str, Any]:
    readiness_next_commands = [str(command) for command in (storage.get("readiness_next_commands") or [])]
    readiness_proof_queue = [str(command) for command in (storage.get("readiness_proof_queue") or [])]
    readiness_proof_queue_preview = [
        str(command)
        for command in (storage.get("readiness_proof_queue_preview") or readiness_proof_queue[:5])
    ]
    issues = [str(issue) for issue in _status_metadata_list(storage.get("issues"))]
    return {
        "source": "status_snapshot_storage",
        "handoff_ready": True,
        "storage_handoff_ready": True,
        "ready_for_operator": True,
        "state_changed": False,
        "changed": [],
        "authorizes_execution": False,
        "authorizes_completion_claim": False,
        "approval_granted": False,
        "storage_status": str(storage.get("status") or "unknown"),
        "storage_available": _status_metadata_bool(storage.get("available")),
        "storage_workspace_local_notes": _status_metadata_bool(storage.get("workspace_local_notes")),
        "storage_recovery_required": _status_metadata_bool(storage.get("recovery_required")),
        "storage_recovery_mode": str(storage.get("recovery_mode") or "none"),
        "storage_recovery_restart_required": _status_metadata_bool(storage.get("recovery_restart_required")),
        "storage_recovery_next_operator_action": str(storage.get("recovery_next_operator_action") or ""),
        "storage_readiness_blocks_completion_claim": _status_metadata_bool(
            storage.get("readiness_blocks_completion_claim")
        ),
        "storage_readiness_next_commands": readiness_next_commands,
        "storage_readiness_next_command_count": len(readiness_next_commands),
        "storage_readiness_next_required_command": str(storage.get("readiness_next_required_command") or ""),
        "storage_readiness_next_proof_command": str(storage.get("readiness_next_proof_command") or ""),
        "storage_readiness_proof_queue": readiness_proof_queue,
        "storage_readiness_proof_queue_count": len(readiness_proof_queue),
        "storage_readiness_proof_queue_preview": readiness_proof_queue_preview,
        "storage_readiness_proof_queue_preview_count": int(
            storage.get("readiness_proof_queue_preview_count") or len(readiness_proof_queue_preview)
        ),
        "storage_readiness_proof_queue_remaining_count": int(
            storage.get("readiness_proof_queue_remaining_count")
            if storage.get("readiness_proof_queue_remaining_count") is not None
            else max(len(readiness_proof_queue) - len(readiness_proof_queue_preview), 0)
        ),
        "storage_readiness_first_proof_command": str(storage.get("readiness_first_proof_command") or ""),
        "storage_recovery_check_tool_command": str(storage.get("recovery_check_tool_command") or ""),
        "storage_recovery_check_command": str(storage.get("recovery_check_command") or ""),
        "storage_recovery_check_api": "/api/storage-recovery-check",
        "storage_recovery_command": str(storage.get("recovery_command") or ""),
        "storage_issues": issues,
        "storage_issue_count": int(storage.get("issue_count") or len(issues)),
        "next_commands": readiness_proof_queue or readiness_next_commands,
        "next_command": (
            str(storage.get("readiness_next_required_command") or "")
            or str(storage.get("readiness_next_proof_command") or "")
            or str(storage.get("recovery_check_tool_command") or "")
            or str(storage.get("recovery_check_command") or "")
        ),
        "next_proof_command": (
            str(storage.get("readiness_next_proof_command") or "")
            or str(storage.get("readiness_first_proof_command") or "")
            or str(storage.get("recovery_check_tool_command") or "")
            or str(storage.get("recovery_check_command") or "")
        ),
        "boundaries": {
            "metadata_only": True,
            "reads_database_file": False,
            "reads_db_file_contents": False,
            "reads_vault_files": False,
            "scans_obsidian_vault": False,
            "writes_files": False,
            "writes_database": False,
            "writes_memory": False,
            "writes_notes": False,
            "queues_approval": False,
            "approves_request": False,
            "approves_requests": False,
            "dismisses_request": False,
            "dismisses_approvals": False,
            "controls_computer": False,
            "calls_external_service": False,
            "executes_tools": False,
            "authorizes_execution": False,
            "authorizes_completion_claim": False,
        },
    }


def _storage_handoff_from_metadata(metadata: dict[str, Any], *, source: str) -> dict[str, Any]:
    readiness_next_commands = [str(command) for command in (metadata.get("storage_readiness_next_commands") or [])]
    readiness_proof_queue = [str(command) for command in (metadata.get("storage_readiness_proof_queue") or readiness_next_commands)]
    readiness_proof_queue_preview = [
        str(command)
        for command in (metadata.get("storage_readiness_proof_queue_preview") or readiness_proof_queue[:5])
    ]
    issues = [str(issue) for issue in (metadata.get("storage_issues") or [])]
    storage = {
        "status": metadata.get("storage_status", "unknown"),
        "available": metadata.get("storage_available", False),
        "workspace_local_notes": metadata.get("storage_workspace_local_notes", False),
        "issues": issues,
        "issue_count": metadata.get("storage_issue_count", len(issues)),
        "recovery_required": metadata.get("storage_recovery_required", False),
        "recovery_mode": metadata.get("storage_recovery_mode", "none"),
        "recovery_restart_required": metadata.get("storage_recovery_restart_required", False),
        "recovery_next_operator_action": metadata.get("storage_recovery_next_operator_action", ""),
        "readiness_blocks_completion_claim": metadata.get("storage_readiness_blocks_completion_claim", False),
        "readiness_next_commands": readiness_next_commands,
        "readiness_next_required_command": metadata.get(
            "storage_readiness_next_required_command",
            metadata.get("storage_readiness_next_proof_command", ""),
        ),
        "readiness_next_proof_command": metadata.get("storage_readiness_next_proof_command", ""),
        "readiness_proof_queue": readiness_proof_queue,
        "readiness_proof_queue_preview": readiness_proof_queue_preview,
        "readiness_proof_queue_preview_count": metadata.get(
            "storage_readiness_proof_queue_preview_count",
            len(readiness_proof_queue_preview),
        ),
        "readiness_proof_queue_remaining_count": metadata.get(
            "storage_readiness_proof_queue_remaining_count",
            max(len(readiness_proof_queue) - len(readiness_proof_queue_preview), 0),
        ),
        "readiness_first_proof_command": metadata.get(
            "storage_readiness_first_proof_command",
            readiness_proof_queue[0] if readiness_proof_queue else "",
        ),
        "recovery_check_tool_command": metadata.get("storage_recovery_check_tool_command", ""),
        "recovery_check_command": metadata.get("storage_recovery_check_command", ""),
        "recovery_command": metadata.get("storage_recovery_command", ""),
    }
    handoff = _storage_handoff(storage)
    handoff["source"] = source
    return handoff


def _with_storage_recovery_check_api_attrs(html: str) -> str:
    command_attr = 'data-storage-recovery-check-command="'
    api_attr = 'data-storage-recovery-check-api='
    tool_attr = ' data-storage-recovery-check-tool-command='
    parts = html.split(command_attr)
    if len(parts) == 1:
        return html
    rewritten = [parts[0]]
    for part in parts[1:]:
        next_tag_end = part.find(">")
        next_tool_attr = part.find(tool_attr)
        if next_tag_end >= 0 and 0 <= next_tool_attr < next_tag_end and api_attr not in part[:next_tag_end]:
            part = part.replace(
                tool_attr,
                ' data-storage-recovery-check-api="/api/storage-recovery-check"' + tool_attr,
                1,
            )
        rewritten.append(command_attr + part)
    return "".join(rewritten)


def _with_harness_verification_gap_attrs(html: str, readiness_digest: dict[str, Any]) -> str:
    card_marker = 'id="jarvis-harness-readiness-digest-card"'
    card_start = html.find(card_marker)
    if card_start < 0:
        return html
    card_end = html.find(">", card_start)
    if card_end < 0:
        return html
    existing_card = html[card_start:card_end]
    if "data-execution-verification-gap-count=" in existing_card:
        return html
    verification_preview = " || ".join(
        str(command)
        for command in list(readiness_digest.get("execution_health_verification_proof_queue_preview") or [])
    )
    attrs = (
        f' data-execution-verification-gap-count="{escape(str(readiness_digest.get("execution_health_verification_gap_count", 0)))}"'
        f' data-execution-verification-first-gap="{escape(str(readiness_digest.get("execution_health_verification_first_gap") or ""))}"'
        f' data-execution-verification-proof-queue-preview="{escape(verification_preview)}"'
        f' data-execution-verification-proof-queue-preview-count="{escape(str(readiness_digest.get("execution_health_verification_proof_queue_preview_count", 0)))}"'
        f' data-execution-verification-proof-queue-remaining-count="{escape(str(readiness_digest.get("execution_health_verification_proof_queue_remaining_count", 0)))}"'
    )
    return html[:card_end] + attrs + html[card_end:]


def _with_execution_verification_required_attrs(html: str) -> str:
    proof_attr = 'data-execution-verification-next-proof-command="'
    required_attr = "data-execution-verification-next-required-command="
    parts = html.split(proof_attr)
    if len(parts) == 1:
        return html
    rewritten = [parts[0]]
    for part in parts[1:]:
        next_tag_end = part.find(">")
        if next_tag_end >= 0 and required_attr not in part[:next_tag_end]:
            proof_value_end = part.find('"')
            proof_value = part[:proof_value_end] if proof_value_end >= 0 else ""
            part = f'data-execution-verification-next-required-command="{escape(proof_value)}" ' + proof_attr + part
        else:
            part = proof_attr + part
        rewritten.append(part)
    return "".join(rewritten)


