def _safety_status_summary(tools, pending_approvals) -> list[str]:
    risk_counts: dict[str, int] = {}
    for tool in tools:
        risk_counts[tool.risk.name] = risk_counts.get(tool.risk.name, 0) + 1
    gated = [
        tool for tool in tools if tool.risk.name in {"PERSONAL_DATA", "EXTERNAL_SIDE_EFFECT", "HIGH_RISK"}
    ]
    return [
        "Safety status shows the live auto-run ceiling, risk inventory, gated tools, and approval queue.",
        "Auto-run ceiling: READ_ONLY and LOCAL_SAFE only.",
        f"Read-only tools: {risk_counts.get('READ_ONLY', 0)}",
        f"Local-safe tools: {risk_counts.get('LOCAL_SAFE', 0)}",
        f"Approval-gated tools: {len(gated)}",
        f"Pending approvals: {len(pending_approvals)}",
        "Command: `safety status`",
        "API: `/api/safety-status`",
        "Rule: this is read-only and does not approve requests, dismiss approvals, run tools, read personal data, control the computer, write files, or queue approvals.",
    ]


def _capability_summary(tools) -> list[str]:
    toolsets: dict[str, int] = {}
    risks: dict[str, int] = {}
    for tool in tools:
        toolsets[tool.toolset] = toolsets.get(tool.toolset, 0) + 1
        risks[tool.risk.name] = risks.get(tool.risk.name, 0) + 1
    top_toolsets = sorted(toolsets.items(), key=lambda item: (-item[1], item[0]))[:6]
    risk_bits = ", ".join(f"{name}={count}" for name, count in sorted(risks.items()))
    lines = [
        f"Registered tools: {len(tools)} across {len(toolsets)} toolsets.",
        f"Risk mix: {risk_bits or 'none'}",
    ]
    if top_toolsets:
        lines.append("Largest areas: " + "; ".join(f"{name}={count}" for name, count in top_toolsets))
    lines.extend(
        [
            "API: `/api/capabilities`",
            "Tool search API: `/api/tool-search?query=approvals`",
            "Tool detail API: `/api/tool-detail?name=run_shell_command`",
            "Risk matrix API: `/api/risk-matrix`",
            "Focus examples: `/api/capabilities?focus=safety`, `/api/capabilities?focus=conversation`",
            "Commands: `capability map`, `tool search: approvals`, `tool detail: run_shell_command`, `risk matrix`",
            "Rule: capability inspection is read-only; risky tools still require approval before execution.",
        ]
    )
    return lines


