def _goal_list_handoff(runtime: JarvisRuntime) -> dict[str, Any]:
    try:
        result = runtime.registry.get("list_goals").handler({"status": "active", "limit": 25})
        metadata = result.metadata if result.ok else {}
    except Exception:
        result = None
        metadata = {}
    handoff = dict(metadata.get("goal_list_handoff") or {})
    if not handoff:
        handoff = {
            "ok": bool(result.ok) if result is not None else False,
            "tool": result.tool_name if result is not None else "list_goals",
            "source": "list_goals" if result is not None else "status_snapshot",
            "status": metadata.get("status", "active"),
            "limit": metadata.get("limit", 25),
            "goal_count": metadata.get("count", 0),
            "goal_ids": [],
            "goals": [],
            "next_commands": {},
            "boundaries": {},
        }
    handoff.setdefault("ok", bool(result.ok) if result is not None else False)
    handoff.setdefault("tool", result.tool_name if result is not None else "list_goals")
    handoff.setdefault("source", "list_goals")
    handoff["goal_list_handoff_ready"] = (
        _status_metadata_bool(metadata.get("goal_list_handoff_ready"))
        if "goal_list_handoff_ready" in metadata
        else bool(handoff)
    )
    _normalize_goal_handoff(handoff)
    handoff["api"] = "/api/goals-list?status=active&limit=25"
    handoff.setdefault(
        "summary",
        [
            "Status goal list handoff source: `list_goals`",
            "Use `goals`, `goal_ids`, and `next_commands` for command-first dashboard routing.",
            "Rule: this status handoff is read-only and never creates goals, changes goal status, completes steps, runs tools, or queues approvals.",
        ],
    )
    return handoff


