def _build_progress_summary(runtime: JarvisRuntime, tool_runs, pending_approvals, tasks, goals, jobs, sessions, memories) -> tuple[dict[str, int], list[str], list[str]]:
    tool_counts: dict[str, int] = {}
    for row in tool_runs:
        tool_counts[row["tool_name"]] = tool_counts.get(row["tool_name"], 0) + 1
    failed_runs = [row for row in tool_runs if not row["ok"]]
    blocked_risky_runs = [
        row
        for row in failed_runs
        if row["risk"] in {"HIGH_RISK", "PERSONAL_DATA", "EXTERNAL_SIDE_EFFECT"}
    ]
    read_only_runs = [row for row in tool_runs if row["risk"] == "READ_ONLY"]
    local_safe_runs = [row for row in tool_runs if row["risk"] == "LOCAL_SAFE"]
    approved_runs = [row for row in tool_runs if row["approved"]]
    enabled_jobs = _dashboard_scheduler_background_state(jobs)["enabled_jobs"]
    build_proof_queue: list[str] = []

    def add_proof(command: str) -> None:
        if command and command not in build_proof_queue:
            build_proof_queue.append(command)

    for row in failed_runs[:3]:
        add_proof(f"verification receipt {row['id']}")
        add_proof(f"execution recovery packet {row['id']}")
        add_proof(f"after-action learning packet {row['id']}")
    for row in pending_approvals[:3]:
        add_proof(f"approval readiness {row['id']}")
        add_proof(f"approval packet {row['id']}")
        add_proof(f"approval chain proof {row['id']}")
    for row in tasks[:2]:
        add_proof(f"task completion packet {row['id']}")
    for goal in goals[:2]:
        if goal["status"] != "active":
            continue
        steps = runtime.store.list_goal_steps(goal["id"])
        open_steps = [step for step in steps if step["status"] != "done"]
        if open_steps:
            add_proof(f"complete goal step {goal['id']} {open_steps[0]['id']}")
    for command in ["build delta", "work block checkpoint", "harness completion", "completion claim gate"]:
        add_proof(command)

    top_tools = ", ".join(
        f"{name} x{count}"
        for name, count in sorted(tool_counts.items(), key=lambda item: (-item[1], item[0]))[:5]
    )
    summary = [
        f"Tool runs reviewed: {len(tool_runs)}",
        f"Top tools: {top_tools or 'none'}",
        f"Read-only/local-safe: {len(read_only_runs)} read-only, {len(local_safe_runs)} local-safe",
        f"Approved high-risk reruns: {len(approved_runs)}",
        f"Failed or blocked runs: {len(failed_runs)}",
        f"Pending approvals: {len(pending_approvals)}",
        f"Blocked risky runs: {len(blocked_risky_runs)}",
        f"Open tasks: {len(tasks)}",
        f"Active goals: {len([goal for goal in goals if goal['status'] == 'active'])}",
        f"Enabled jobs: {len(enabled_jobs)}",
    ]
    if pending_approvals:
        for row in pending_approvals[:3]:
            summary.append(f"Approval #{row['id']} {row['tool_name']}: {row['user_input']}")
            summary.append(f"Readiness: `approval readiness {row['id']}`")
            summary.append(f"Last look: `approval packet {row['id']}`")
            summary.append(f"Proof: `approval chain proof {row['id']}`")
    if tasks:
        summary.append(f"Top task: #{tasks[0]['id']} {tasks[0]['body']}")
    if goals:
        first_goal = goals[0]
        steps = runtime.store.list_goal_steps(first_goal["id"])
        open_steps = [step for step in steps if step["status"] != "done"]
        next_step = open_steps[0]["body"] if open_steps else "define next step"
        summary.append(f"Top goal: #{first_goal['id']} {first_goal['title']} -> {next_step}")
    if sessions:
        summary.append(f"Latest session: {sessions[0]['session_id']} at {sessions[0]['last_at']}")
    if memories:
        summary.append(f"Latest memory: [{memories[0]['category']}] {memories[0]['title']}")
    summary.append(f"Build proof queue count: {len(build_proof_queue)}")
    summary.append(f"Build next required: `{build_proof_queue[0]}`" if build_proof_queue else "Build next required: none")
    summary.append(
        "Build proof queue: "
        + (", ".join(f"`{command}`" for command in build_proof_queue) if build_proof_queue else "none")
    )

    next_moves = [
        "Next: run `roadmap` to choose the next assistant layer.",
        "Next: run `approval review`, then `approval readiness #ID`, `approval packet #ID`, and `approval chain proof #ID`, before approving blocked risky work.",
        "Next: run `focus brief` before hands-on coding or desktop-control work.",
        "Rule: keep new connectors read-only first, with personal-data and side-effect tools approval-gated.",
        "Rule: priority goals do not override the operator's explicit stop times, work windows, pause commands, or newer instructions.",
    ]
    metrics = {
        "tool_runs": len(tool_runs),
        "read_only_runs": len(read_only_runs),
        "local_safe_runs": len(local_safe_runs),
        "approved_runs": len(approved_runs),
        "failed_runs": len(failed_runs),
        "blocked_risky_runs": len(blocked_risky_runs),
        "pending_approvals": len(pending_approvals),
        "open_tasks": len(tasks),
        "active_goals": len([goal for goal in goals if goal["status"] == "active"]),
        "enabled_jobs": len(enabled_jobs),
        "build_proof_queue_count": len(build_proof_queue),
    }
    return metrics, summary, next_moves


def _build_delta_summary(tool_runs, recent_messages, pending_approvals) -> list[str]:
    failed_runs = [row for row in tool_runs if not row["ok"]]
    blocked_risky_runs = [
        row
        for row in failed_runs
        if row["risk"] in {"HIGH_RISK", "PERSONAL_DATA", "EXTERNAL_SIDE_EFFECT"}
    ]
    user_messages = [row for row in recent_messages if row["role"] == "user"]
    assistant_messages = [row for row in recent_messages if row["role"] == "assistant"]
    lines = [
        f"Recent tool runs reviewed: {len(tool_runs)}",
        f"Recent messages visible: {len(recent_messages)}",
        f"Pending approvals: {len(pending_approvals)}",
        f"Blocked risky runs: {len(blocked_risky_runs)}",
        "API: `/api/build-delta`",
        "Command: `build delta`",
        "Save: `save build delta` writes the latest checkpoint window into Obsidian Reflections.",
        "Rule: this summary reads the latest checkpoint window only; it does not call models, run tools, write notes, control the computer, or queue approvals.",
        "Rule: priority goals do not override the operator's explicit stop times, work windows, pause commands, or newer instructions.",
    ]
    if tool_runs:
        lines.append(f"Latest tool: {tool_runs[0]['tool_name']} [{tool_runs[0]['risk']}] at {tool_runs[0]['created_at']}")
    if user_messages:
        lines.append(f"Latest user ask: {user_messages[-1]['content'][:180]}")
    if assistant_messages:
        lines.append(f"Latest Jarvis response: {assistant_messages[-1]['content'][:180]}")
    lines.append("Safe next checks: `build progress`, `chat continuity brief`, `approval review`, `approval readiness #ID`, `approval packet #ID`, then `approval chain proof #ID`.")
    return lines


def _chat_context_summary(runtime: JarvisRuntime, memories, skills, preferences, sessions) -> tuple[list[str], list[str]]:
    profile_text = runtime.vault.read_profile(max_chars=1200).strip()
    recent_messages = runtime.store.recent_messages(limit=6, session_id=runtime.session_id)
    summary = [
        f"Profile context: {'present' if profile_text and profile_text != '# Profile' else 'empty'}",
        f"Active preferences available to chat: {len(preferences)}",
        f"Recent memories available: {min(len(memories), 8)} shown / {len(memories)} loaded",
        f"Active reviewed skills available: {len(skills)}",
        f"Recent sessions indexed: {len(sessions)}",
        f"Current session messages: {len(recent_messages)}",
        "Chat answers can use this context, but tool execution still goes through planner, registry, permission policy, and approvals.",
    ]
    commands = [
        "Preview: `chat context: what should Jarvis do next?`",
        "Prompt preview: `chat prompt preview: how should Jarvis talk about memory?`",
        "Save: `save chat context: how should Jarvis use memory?`",
        "Chat API: POST `/api/chat` with `{ \"message\": \"jarvis status\" }`",
        "API: `/api/chat-context?prompt=what%20should%20Jarvis%20remember`",
        "Prompt preview API: `/api/chat-prompt-preview?prompt=how%20should%20Jarvis%20talk%20about%20memory`",
    ]
    return summary, commands


