def _morning_startup_summary(tasks, goals, pending_approvals, jobs) -> list[str]:
    enabled_jobs = _dashboard_scheduler_background_state(jobs)["enabled_jobs"]
    lines = [
        "Morning startup gives Jarvis a safe first move for the day or after a long break.",
        f"Pending approvals: {len(pending_approvals)}",
        f"Open tasks: {len(tasks)}",
        f"Active goals: {len([goal for goal in goals if goal['status'] == 'active'])}",
        f"Enabled scheduled jobs: {len(enabled_jobs)}",
        "Command: `morning startup`",
        "API: `/api/morning-startup`",
        "Rule: this is read-only and does not approve requests, complete tasks, write notes, execute tools, or control the computer.",
    ]
    if pending_approvals:
        approval_id = pending_approvals[0]["id"]
        lines.append(f"Suggested first safe move: run `approval readiness {approval_id}`, `approval packet {approval_id}`, then `approval chain proof {approval_id}` before deciding.")
