def _channel_health_dashboard_summary(runtime: JarvisRuntime) -> tuple[list[str], bool, str]:
    try:
        result = runtime.registry.get("channel_health").handler({})
    except Exception as exc:
        diagnostic = type(exc).__name__
        return (
            [
                "Channel health tool unavailable.",
                f"Diagnostic: {diagnostic}",
                "API: `/api/channel-health`",
                "Rule: dashboard channel health is read-only and must not send messages, start calls, queue approvals, read message content, or control the computer.",
            ],
            True,
            diagnostic,
        )
    if not result.ok:
        diagnostic = "tool_result_not_ok"
        return (
            [
                "Channel health tool unavailable.",
                f"Diagnostic: {diagnostic}",
                "API: `/api/channel-health`",
                "Rule: dashboard channel health is read-only and must not send messages, start calls, queue approvals, read message content, or control the computer.",
            ],
            True,
            diagnostic,
        )
    metadata = result.metadata if result.ok else {}
    channels = _status_metadata_list(metadata.get("channels", []))
    rows = [
        "Channel health uses existing audit metadata only.",
        "API: `/api/channel-health`",
        f"Window: {metadata.get('window_days', 'unknown')} days; rows reviewed: {metadata.get('rows_reviewed', 0)} / {metadata.get('bounded_rows_limit', 'bounded')}"
        + (
            " (bounded sample; older matching rows may exist)."
            if _status_metadata_bool(metadata.get("row_sample_truncated"))
            else "."
        ),
        f"Content suppression: {'on' if _status_metadata_bool(metadata.get('content_suppressed')) else 'unknown'}.",
        "Rule: no recipient names, message text, approval text, connector output snippets, live sends, calls, approvals, external calls, or computer control.",
    ]
    if not channels:
        rows.append("No channel audit rows found yet.")
        return rows, False, ""
    for channel in channels:
        if not isinstance(channel, dict):
            continue
        channel_id = str(channel.get("channel") or "unknown_channel")
        label = channel_id.replace("_", " ").title()
        rows.append(
            f"{label}: last success {channel.get('last_success_at', 'never')}; "
            f"last failure {channel.get('last_failure_at', 'never')}; "
            f"stage {channel.get('last_failure_stage', 'none')}; "
            f"7d successes {channel.get('success_count_7d', 0)}."
        )
    return rows, False, ""


