def _approval_review_summary(runtime: JarvisRuntime, pending_approvals) -> list[str]:
    if not pending_approvals:
        return [
            "No pending approvals.",
            "High-risk actions from web chat still create approval receipts instead of running.",
            "API: `/api/approvals`",
            "History API: `/api/approval-history`",
            "Detail API: `/api/approval-detail?id=1`",
            "Execution packet API: `/api/approval-packet?id=1`",
        ]
    lines = [
        f"{len(pending_approvals)} pending approval(s).",
        "Review each request before approving; run the last-look packet because approval reruns the exact queued request once.",
    ]
    for row in pending_approvals[:5]:
        lines.append(f"Approval #{row['id']} {row['tool_name']}: {row['user_input']}")
        lines.append(f"Detail: `approval detail {row['id']}` or `/api/approval-detail?id={row['id']}`")
        lines.append(f"Readiness: `approval readiness {row['id']}` or `/api/approval-readiness?id={row['id']}`")
        lines.append(f"Last look: `approval packet {row['id']}` or `/api/approval-packet?id={row['id']}`")
        lines.append(f"Proof chain: `approval chain proof {row['id']}` or `/api/approval-chain-proof?id={row['id']}`")
        lines.append(f"Decide: `approve approval {row['id']}` or `dismiss approval {row['id']}`")
    lines.append("API: `/api/approvals`")
    lines.append("History API: `/api/approval-history`")
    return lines


def _work_queue_summary(runtime: JarvisRuntime, tasks, goals, pending_approvals, jobs) -> list[str]:
    enabled_jobs = _dashboard_scheduler_background_state(jobs)["enabled_jobs"]
    lines = [
        "Safe order: review context, clear/ignore approval blockers, work open tasks, then advance goal steps.",
        f"Pending approvals: {len(pending_approvals)}",
        f"Open tasks: {len(tasks)}",
        f"Active goals: {len([goal for goal in goals if goal['status'] == 'active'])}",
        f"Enabled scheduled jobs: {len(enabled_jobs)}",
    ]
    if pending_approvals:
        lines.append(f"First blocker: approval #{pending_approvals[0]['id']} {pending_approvals[0]['tool_name']}")
        lines.append(f"Readiness command: `approval readiness {pending_approvals[0]['id']}`")
        lines.append(f"Last-look command: `approval packet {pending_approvals[0]['id']}`")
        lines.append(f"Proof command: `approval chain proof {pending_approvals[0]['id']}`")
    if tasks:
        task = tasks[0]
        priority = f" [{task['priority']}]" if task["priority"] != "normal" else ""
        lines.append(f"First task: #{task['id']} {task['body']}{priority}")
    active_goals = [goal for goal in goals if goal["status"] == "active"]
    if active_goals:
        goal = active_goals[0]
        open_steps = [step for step in runtime.store.list_goal_steps(goal["id"]) if step["status"] != "done"]
        next_step = open_steps[0]["body"] if open_steps else "define the next step"
        lines.append(f"First goal: #{goal['id']} {goal['title']} -> {next_step}")
    lines.append("API: `/api/work-queue`")
    lines.append("Command: `work queue`")
    lines.append("Selected AGI target readiness is returned as structured `doctor_agi_next_*` metadata for handoff clients.")
    lines.append("Rule: this is read-only and does not complete tasks, approve requests, execute tools, write notes, call models, control the computer, or queue approvals.")
    return lines


def _next_action_packet_summary(runtime: JarvisRuntime, tasks, goals, pending_approvals, jobs) -> list[str]:
    enabled_jobs = _dashboard_scheduler_background_state(jobs)["enabled_jobs"]
    lines = [
        "Choose one proposed next move before acting.",
        f"Pending approvals: {len(pending_approvals)}",
        f"Open tasks: {len(tasks)}",
        f"Active goals: {len([goal for goal in goals if goal['status'] == 'active'])}",
        f"Enabled scheduled jobs: {len(enabled_jobs)}",
        "API: `/api/next-action-packet`",
        "Command: `next action packet`",
        "Selected AGI target readiness is returned as structured `doctor_agi_next_*` metadata for handoff clients.",
        "Rule: this is read-only and does not complete tasks, approve requests, write notes, execute tools, call models, control the computer, or queue approvals.",
    ]
    if pending_approvals:
        approval_id = pending_approvals[0]["id"]
